  box-sizing: border-box;
  font-family: "DM Sans", sans-serif;
  /* background: linear-gradient(180deg, #CFE2EB 24.52%, #C4E4F4 100%); */
  background-color: #fbfafc;
}
a,p,li,span,div,h1,h2,h3,h4,h5,h6,figure{
  text-decoration: none;
  list-style-type: none;
  padding: 0;
  margin: 0;
}
a{
  color: black;
}

.headerContainer{
  max-width: 1860px;
  margin: 0 auto;
  padding: 10px 20px;
}
.container{
  max-width: 1500px;
  margin: 0 auto;
  padding:16px 72px;
}
.swal2-container {
  z-index: 9999999999 !important;
}

@media only screen and (max-width: 950px) {
.container{
  padding:20px;
}
}

@media only screen and (max-width: 950px) {
  .headerContainer{
  padding: 5px;
}
}
.sectionTitle{
  font-size: 24px;
  font-weight: 700;
  color: rgba(32, 114, 153, 1);
  border-bottom: 1px solid rgba(32, 114, 153, 1);
    padding-bottom: 15px;
    margin: 30px 0;
}

@media only screen and (max-width: 950px) {
  .sectionTitle{
  font-size: 24px;
  font-weight: 700;
    padding-bottom: 15px;
    margin-top: 0;
}
}
.footerPageTitle{
      font-size: 40px;
    font-weight: 700;
    color: #207299;
    text-align: center;
    margin: 30px 0;
}
.footerPageInfo{
      width: 80%;
    margin: 30px auto 40px;
    font-size: 20px;
    line-height: 30px;
    font-weight: 400;
    color: #207299;
}

@media only screen and (max-width: 950px) {
  .footerPageTitle{
    font-size: 24px;
    font-weight: 700;
    margin: -10px 0 10px 0;
}
.footerPageInfo{
    width: 100%;
    margin: 10px auto 40px;
