}
}

/* mobile swiper slider pagination style  */
.swiper-pagination-bullet{
  width: 10px !important;
  height: 10px !important;
  background:  rgba(32, 114, 153, 1)!important;
  opacity: 1 !important;
  margin-top: 20px !important;
  margin: -10px 5px !important;
  transition: .5s ease !important;
}
 .swiper-pagination-bullet-active { 
  width: 18px !important;
  height: 10px !important;
  border-radius: 5px !important;
  background-color: rgba(1, 148, 219, 1) !important;
}
.swiper-slide {
  position: relative;
  height: 100%;
}

/* headerde olan sliderin smooth(yumusaq) getmesi ve ortalanmasi ucun style */
.headerCategorySwiperSlider .swiper-wrapper {
    align-items: center !important;
  transition-timing-function: linear !important;
}

/* footerde olan brand sliderin smooth(yumusaq) getmesi ve ortalanmasi  ucun style */
.brandSwiperSlider .swiper-wrapper {
    align-items: center !important;
  transition-timing-function: linear !important;
}
/* footerdeki xeritenin ustunde olan artiq melumatlari goturmek ucun style */
.leaflet-control-attribution{
  display: none !important;
}

/* product detail page product images slider style */


.swiper-slide-thumb-active img {
    opacity: 1 !important;
}
.prDetailNextBtn,
.prDetailPrevBtn{
position: absolute;
top: 33px;
width: 35px;
height: 35px;
background-color: white;
display: flex;
justify-content: center;
align-items: center;
border-radius: 7px;
}
.prDetailPrevBtn{
    left: 14px;
    cursor: pointer;
}
.prDetailNextBtn{
  right: 14px;
  cursor: pointer;
}

.prDetailCreditMonthsSlider{
  width: 250px;
      flex: 1;
    min-width: 0; 
}
.prDetailCreditMonthsSlider.swiper{
  margin: 0 !important;
}

@media only screen and (max-width: 1320px) {
  .prDetailCreditMonthsSlider{
  width: 120px;
}
}

@media only screen and (max-width: 950px) {
  .prDetailCreditMonthsSlider{
  width: 150px;
}
}
.prDetailCreditMonthsSlider .swiper-wrapper {
  align-items: center;
}
@media only screen and (max-width: 950px) {
 .prDetailNextBtn,
.prDetailPrevBtn{
top: 20px;
width: 22px;
height: 22px;
border-radius: 5px;
}
.prDetailPrevBtn{
    left: 4px;
}
.prDetailNextBtn{
  right: 4px;
