.webCategoryArea {
  position: absolute;
  top: 42px;
  left: 0;
  z-index: 9999999;

  .categoryAndSubcategoryArea {
    display: flex;
    border-radius: 0 16px 16px 0;
    overflow: hidden;
    box-shadow: 8px 4px 32px rgba(0, 0, 0, 0.08);
    background: #ffffff;
  }

  .categories {
    width: 260px;
    height: calc(100vh - 80px);
    background: #f7f8fa;
    display: flex;
    flex-direction: column;
    gap: 6px;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 10px 0;
    transform-origin: top;
    animation: slideDown 0.40s cubic-bezier(0.25, 0.8, 0.25, 1) forwards;

    &::-webkit-scrollbar {
      width: 3px;
    }

    &::-webkit-scrollbar-thumb {
      background: #d0d0d0;
      border-radius: 10px;
    }

    .categoryBtn {
      display: flex;
      align-items: center;
      gap: 5px;
      width: 100%;
      height: 36px;
      display: flex;
      align-items: center;
      padding: 2px 16px;
      transition:
       background-color 0.1s ease,
        color 0.1s ease;
      font-size: 15px;
      font-weight: 500;
      color: #444;
      text-decoration: none;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      &:hover {
        background: #e2e2e2;
      }
      .categoryImg{
        width: 35px;
        height: 35px;
        object-fit: contain;
      }
    }

    .activeBtn {
      background: #d1dfff;
      color: #856404;
      font-weight: 600;
      border-left: 3px solid #b5cbfc;
    }

    .currentPageBtn {
      background: #e8f0fe;
      color: #0048de;
      font-weight: 600;
      border-left: 3px solid #0048de;
    }
  }

  .subCategoryWrapper {
    background: #ffffff;
    border-left: 1px solid #f0f0f0;
    overflow: hidden;
    width: 0;
    opacity: 0;
    transition:
      width 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
      opacity 0.3s ease;

    &.showSubCategories {
      width: 300px;
      opacity: 1;
    }

    .subCategoryInner {
      width: 300px;
      height: calc(100vh - 90px);
      overflow-y: auto;
      padding: 10px 0;

      &::-webkit-scrollbar {
        width: 3px;
      }
      &::-webkit-scrollbar-thumb {
        background: #e0e0e0;
        border-radius: 10px;
      }
    }

    .subcategory {
      .subTitle,
      .childLink {
        display: block;
        padding: 10px 20px;
        color: #555;
        transition: all 0.2s ease;
        font-size: 14px;
        text-decoration: none;

        &:hover {
          background: #f5f7fb;
          color: #1a1a1a;
          padding-left: 24px;
        }
      }

      .subTitle {
        color: #1a1a1a;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.04em;
        margin-top: 6px;

        &:first-child {
          margin-top: 0;
        }
      }

      .activeSubTitle {
        color: #0048de;
        background: #e8f0fe;
        border-left: 3px solid #0048de;
      }

      .childLink {
        font-weight: 400;
        color: #666;
        font-size: 13.5px;

        &:hover {
          color: #2563eb;
          background: #f0f4ff;
        }
      }

      .activeChildLink {
        color: #0048de;
        background: #f0f4ff;
        font-weight: 600;
        border-left: 3px solid #0048de;
      }
    }
  }
}

@keyframes slideDown {
  from {
    transform: scaleY(0);
    opacity: 0;
  }
  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

@media only screen and (max-width: 950px) {
  .webCategoryArea {
    display: none;
  }
}

