src/components/HomePageSections/MainBann:
.mainBannersWebWrapper {
  width: 100%;
  height: 500px;

  display: flex;
  align-items: stretch;

  gap: 20px;

  // =====================================================
  // LEFT SIDE
  // =====================================================
  .mainBannersLeft {
    width: 64%;
    height: 100%;

    min-width: 0;

    overflow: hidden;
    border-radius: 14px;

    // Swiper
    .leftSlider {
      width: 100%;
      height: 100%;
    }

    // Hər slider item
    .sliderBanner {
      position: relative;

      display: block;

      width: 100%;
      height: 100%;

      overflow: hidden;
      border-radius: 14px;
    }
  }

  // =====================================================
  // RIGHT SIDE
  // =====================================================
  .mainBannersRight {
    width: 36%;
    height: 100%;

    display: flex;
    flex-direction: column;

    gap: 20px;

    // Sağdakı hər banner
    .rightBanner {
      position: relative;

      display: block;

      width: 100%;

      // 2 banner + 20px gap
      height: calc((100% - 20px) / 2);

      overflow: hidden;

      border-radius: 14px;
    }
  }

  // =====================================================
  // BANNER IMAGE
  // =====================================================
  .bannerImage {
    position: absolute;

    top: 0;
    left: 0;

    width: 100%;
    height: 100%;

    object-fit: cover;

    border-radius: 14px;

    transition: opacity 0.3s ease;
  }

  // =====================================================
  // LOADING
  // =====================================================
  .loadingImg {
    position: absolute;

    z-index: 10;

    top: 50%;
    left: 50%;

    transform: translate(-50%, -50%);

    width: 70px;
    height: 70px;

    object-fit: contain;
  }
}

// =====================================================
// MOBILE
// =====================================================

.mobileMainBannersWrapper {
  display: none;
}

// =====================================================
// RESPONSIVE
// =====================================================

@media only screen and (max-width: 1200px) {
  .mainBannersWebWrapper {
    height: 450px;
  }
}

@media only screen and (max-width: 1050px) {
  .mainBannersWebWrapper {
    height: 400px;

    gap: 15px;

    .mainBannersRight {
      gap: 15px;

      .rightBanner {
        height: calc((100% - 15px) / 2);
      }
    }
  }
}

// 950px-dən aşağı desktop banner gizlənir
@media only screen and (max-width: 950px) {
  .mainBannersWebWrapper {
    display: none;
  }

  .mobileMainBannersWrapper {
    display: block;
  }
}
